def polynomial_to_string(n: int, coeffs: list) -> str:
    terms = []
    for i, coeff in enumerate(coeffs):
        if coeff == 0:
            continue
        degree = n - i
        # Determine the sign
        if degree == 0:
            # Constant term
            if coeff > 0:
                sign = '+' if terms else ''
            else:
                sign = '-'
            abs_coeff = abs(coeff)
            term = f"{sign}{abs_coeff}"
        else:
            # Non-constant term
            if coeff > 0:
                sign = '+' if terms else ''
            else:
                sign = '-'
            abs_coeff = abs(coeff)
            # Format the variable part
            if degree == 1:
                var_part = 'x'
            else:
                var_part = f'x^{degree}'
            # If coefficient is 1, omit the number
            if abs_coeff == 1:
                term = f"{sign}{var_part}"
            else:
                term = f"{sign}{abs_coeff}{var_part}"
        terms.append(term)

    if not terms:
        return '0'

    return ''.join(terms)
