    mapping = {}
    for enc, orig in zip(encoded, original):
        if enc in mapping:
            if mapping[enc] != orig:
                return "Failed"
        else:
            mapping[enc] = orig

    # Check if all letters are represented in the mapping
    # The problem says "not all letters are represented in the mapping"
    # We need to check if the mapping covers all 26 letters? Or all letters in the message?
    # Let's check: the example "AA" -> "AB" fails because A maps to both A and B.
    # The second example works.
    # Let's check if the mapping has all 26 letters.
    # Actually, let's re-read: "not all letters are represented in the mapping"
    # This likely means that the mapping should be a complete substitution cipher (all 26 letters).
    # Let's check if the set of keys in mapping has size 26.
    if len(mapping) != 26:
        return "Failed"

    # Also check that the mapping is a bijection (each original letter maps to exactly one encoded letter)
    # Actually, the problem says "builds a mapping from encoded letters to their original letters"
    # So we need to ensure that the mapping is consistent and complete.
    # Let's also check that no two encoded letters map to the same original letter (to ensure it's a valid cipher)
    orig_set = set(mapping.values())
    if len(orig_set) != 26:
        return "Failed"

    # Now decode the message
    decoded = []
    for char in message:
        if char in mapping:
            decoded.append(mapping[char])
        else:
            return "Failed"

    return ''.join(decoded)
